import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BV21bweQ.js";const p=JSON.parse('{"title":"众生录 · 表层人物","description":"","frontmatter":{},"headers":[],"relativePath":"表层/人物/index.md","filePath":"表层/人物/index.md","lastUpdated":1787066340000}'),l={name:"表层/人物/index.md"};function h(i,a,n,s,d,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="众生录-·-表层人物" tabindex="-1">众生录 · 表层人物 <a class="header-anchor" href="#众生录-·-表层人物" aria-label="Permalink to &quot;众生录 · 表层人物&quot;">​</a></h1><blockquote><p>本名录从<strong>表层视角</strong>介绍这个世界的人物——只收录大陆生灵公开可见的一面。这些人物背后还有不为人知的真相档案，藏在<a href="./../../中层/人物/" class="layer-link" data-layer="中层">中层人物真相档案</a>中；想深挖时，跟随链接上的层级徽标即可。</p></blockquote><h2 id="红星孤儿院" tabindex="-1">红星孤儿院 <a class="header-anchor" href="#红星孤儿院" aria-label="Permalink to &quot;红星孤儿院&quot;">​</a></h2><p>故事开始的地方。狼国境内的一座孤儿院，收容各族孤儿。</p><h3 id="维斯塔-——-孤儿院院长" tabindex="-1">维斯塔 —— 孤儿院院长 <a class="header-anchor" href="#维斯塔-——-孤儿院院长" aria-label="Permalink to &quot;维斯塔 —— 孤儿院院长&quot;">​</a></h3><p>红星孤儿院院长，孩子们信赖的长者。共同体时期的神明&quot;红星&quot;之名，在史书中依旧闪耀。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./维斯塔">维斯塔</a></p></blockquote><h3 id="艾莉芙-——-副院长" tabindex="-1">艾莉芙 —— 副院长 <a class="header-anchor" href="#艾莉芙-——-副院长" aria-label="Permalink to &quot;艾莉芙 —— 副院长&quot;">​</a></h3><p>精灵族的隐居者，红星孤儿院副院长。生人勿近，却对孩子们温和包容。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./艾莉芙">艾莉芙</a></p></blockquote><h3 id="拉斯塔-——-爱冒险的狐族少女" tabindex="-1">拉斯塔 —— 爱冒险的狐族少女 <a class="header-anchor" href="#拉斯塔-——-爱冒险的狐族少女" aria-label="Permalink to &quot;拉斯塔 —— 爱冒险的狐族少女&quot;">​</a></h3><p>红星孤儿院的孤儿，阳光开朗，是孩子们公认的领头者，一心想走出孤儿院去看看外面的世界。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./拉斯塔">拉斯塔</a></p></blockquote><h3 id="狼族少年-——-失忆的孤儿" tabindex="-1">狼族少年 —— 失忆的孤儿 <a class="header-anchor" href="#狼族少年-——-失忆的孤儿" aria-label="Permalink to &quot;狼族少年 —— 失忆的孤儿&quot;">​</a></h3><p>被拉斯塔在山洞中发现并带回孤儿院的失忆少年。沉默寡言，与孩子们保持着距离。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./狼族少年">狼族少年</a></p></blockquote><h2 id="龙族与传说" tabindex="-1">龙族与传说 <a class="header-anchor" href="#龙族与传说" aria-label="Permalink to &quot;龙族与传说&quot;">​</a></h2><h3 id="古斯塔夫-——-龙王" tabindex="-1">古斯塔夫 —— 龙王 <a class="header-anchor" href="#古斯塔夫-——-龙王" aria-label="Permalink to &quot;古斯塔夫 —— 龙王&quot;">​</a></h3><p>传说中的龙王，龙族隐居地的守护者。关于龙族的目击传说里，总有他的影子。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./古斯塔夫">古斯塔夫</a></p></blockquote><h2 id="鹿国高层" tabindex="-1">鹿国高层 <a class="header-anchor" href="#鹿国高层" aria-label="Permalink to &quot;鹿国高层&quot;">​</a></h2><h3 id="龙鹿-——-鹿族高层领袖" tabindex="-1">龙鹿 —— 鹿族高层领袖 <a class="header-anchor" href="#龙鹿-——-鹿族高层领袖" aria-label="Permalink to &quot;龙鹿 —— 鹿族高层领袖&quot;">​</a></h3><p>鹿国顶尖领袖之一，从无名之辈一路崛起的传奇人物。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./龙鹿">龙鹿</a></p></blockquote><h2 id="狼族的旧日传说" tabindex="-1">狼族的旧日传说 <a class="header-anchor" href="#狼族的旧日传说" aria-label="Permalink to &quot;狼族的旧日传说&quot;">​</a></h2><h3 id="小白狼-——-村庄里的白色小狼" tabindex="-1">小白狼 —— 村庄里的白色小狼 <a class="header-anchor" href="#小白狼-——-村庄里的白色小狼" aria-label="Permalink to &quot;小白狼 —— 村庄里的白色小狼&quot;">​</a></h3><p>南方狼村收养的白色小狼，狼族少年青梅竹马的玩伴。在奴隶队袭击村庄时死去。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./小白狼">小白狼</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../种族总览">种族总览</a></li><li><a href="./../历史/">表层历史</a></li><li><a href="./../../中层/世界/特殊地点" class="layer-link" data-layer="中层">红星孤儿院</a> 　→ 含中层真相，注意徽标</li><li><a href="./../../中层/人物/" class="layer-link" data-layer="中层">人物真相档案</a></li><li><a href="./../../底层/人物/" class="layer-link" data-layer="底层">元层面人物</a></li></ul><hr>',32)])])}const q=e(l,[["render",h]]);export{p as __pageData,q as default};
